# setting up the Elasticsearch connection

import boto3
from opensearchpy import OpenSearch, RequestsHttpConnection, AWSV4SignerAuth
import logging
from config import Config
from typing import List
from repositories.vector_db_repo_abc import VectorDbRepoABC
from services.util_service import UtilService
from data.face_vector_dto import FaceVectorDto
import random
import time

class OpenSearchRepo(VectorDbRepoABC):
    def __init__(self):
        self._configs = Config.get()
        self._logger = logging.getLogger(self._configs.LOGGER_NAME_IMAGE_SEARCH_REPO)
        # self.min_cosine = self._configs.MIN_COSINE_SIMILARITY_VECTOR_DB
        self.max_distance = self._configs.MAX_SIMILARITY_DISTANCE_VECTOR_DB
        self._oss = None

        # initialize the client
        region = self._configs.IMAGE_SEARCH_REPO_REGION
        es_host = self._configs.IMAGE_SEARCH_REPO_HOST
        service = self._configs.IMAGE_SEARCH_SERVICE_NAME
        credentials = boto3.Session().get_credentials()
        awsauth =AWSV4SignerAuth(credentials, region, service)
        self._oss = OpenSearch(
            hosts = [{'host': es_host, 'port': 443}],
            http_auth = awsauth,
            use_ssl = True,
            verify_certs = True,
            connection_class = RequestsHttpConnection,
            timeout=5
        )

        # idx = self._oss.indices.get(index="idx_face")
        # self._logger.info(f'created image search client: {idx}')


    def search(self, vector, num = 7, min_score=0.002138) -> List[FaceVectorDto]:
        query = {
            "size": num, # Number of nearest vectors to return, could be less if the _score of the matched vector < min_score 
            "min_score": min_score, # The minimum relevance socre between the queried vector to the matched vectors, based on obama test
            "query": {"knn": {"face_img_vector": {"vector": vector, "k": num}}},
            # "_source": False, # True (default) to have the query return the vectors, False if no need
            "fields": ["src_url","s3_key","site","title"],
        }
        try:
            res = self._oss.search(request_timeout=20, index='idx_face',
                            body=query)
            hits = res['hits']['hits']
            sorted_hits = sorted(hits, key=lambda x: x['_score'], reverse=True) # desc order
            results: List[FaceVectorDto] = []
            for hit in sorted_hits:
                vector_www = hit['_source']['face_img_vector']
                # cosine = UtilService.find_cosine_similarity(vector, vector_www)
                distance = UtilService.find_cosine_distance(vector, vector_www)
                if distance <= self.max_distance:
                    results.append(FaceVectorDto(
                        hit['fields']['src_url'][0],
                        hit['fields']['s3_key'][0],
                        hit['_source'].get('s3_face_key',''),
                        hit['fields'].get('title',[''])[0],
                        hit['fields'].get('site',[''])[0],
                        hit['_score'],
                        hit['_id']
                    ))
                else:
                    # we discard any vectors that no longer meets the minimum cosine similarity score
                    break
            return results
        except Exception as e:
            self._logger.error(f'failed to search similar faces with error {e}')
            return []

    
    def search_by_url(self, url):
        query = {
            "query": {
                "term": {
                    "src_url": {
                        "value": url
                    }
                }
            },
            "_source": False,
            "fields": ["src_url"]
        }

        return self._oss.search(request_timeout=10, index='idx_face',
                                body=query)
    
    def image_processed(self, url):
        try:
            res = self.search_by_url(url)
            hits = res['hits']['total']['value']
            return hits > 0
        except Exception as e:
            self._logger.error(f'querying for {url} results in connection error: {e}')
            return False

    def insert(self, vector, img_src_url, img_s3_key, site_url='', site_title='', face_s3_key='', retries=3):
        """
        insert a new image vector document into the index

        :param vector: the vector of a face in the image
        :param img_src_url: the url of the image
        :param img_s3_key: the s3 key of the image
        :param site_url: the url of the site where the image is found
        :param site_title: the title of the site where the image is found
        :param face_s3_key: the s3 key of the face image extracted from the image
        :return: the id of the inserted document
        """
        for attempt in range(1, retries + 1):
            try:
                return self._oss.index(index='idx_face',
                            body={
                                "face_img_vector": vector, 
                                "src_url": img_src_url,
                                "s3_key": img_s3_key,
                                "site": site_url,
                                "title": site_title,
                                "s3_face_key": face_s3_key
                            })  
            except Exception as e:
                # Log the error
                self._logger.warning(f"Attempt {attempt} to insert {img_s3_key} failed: {e}")
                # Determine if retries are still available
                if attempt < retries:
                    # Apply exponential backoff with jitter
                    backoff = 2 ** (attempt - 1) + random.uniform(0, 1)
                    self._logger.info(f"Retrying in {backoff:.2f} seconds...")
                    time.sleep(backoff)
                else:
                    self._logger.error(f'inserting {img_s3_key} results in error: {e}')
                    return None
    
    def search_by_id(self, document_id):
        return self._oss.get(index='idx_face', id=document_id)

